 void catalog(LinearLayout target,String type,String genre){
  final int ticket=epoch;String key="cinema.catalog."+type+"."+genre;JSONArray cache=null;try{cache=new JSONArray(prefs.getString(key,""));}catch(Exception ignored){}
  if(cache!=null&&cache.length()>0){shelf(target,cache,type,false);chooseHero(cache,type,genre);if(System.currentTimeMillis()-prefs.getLong(key+".time",0)<6*60*60*1000L)return;}
  if(target.getChildCount()==0)target.addView(text("正在读取影片信息…",12,muted()));
  job(()->{try{JSONArray items=CinemaCatalogClient.json("https://v3-cinemeta.strem.io/catalog/"+type+"/top"+(genre.isEmpty()?"":"/genre="+Net.esc(genre))+".json").optJSONArray("metas");if(items==null||items.length()==0)throw new IllegalStateException("empty catalog");prefs.edit().putString(key,items.toString()).putLong(key+".time",System.currentTimeMillis()).apply();runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();shelf(target,items,type,false);chooseHero(items,type,genre);});}catch(Exception e){runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;if(target.getChildCount()==1&&target.getChildAt(0) instanceof TextView){TextView message=(TextView)target.getChildAt(0);message.setText("目录暂时无法读取 · 点此重试");message.setOnClickListener(v->catalog(target,type,genre));}});}});
 }
 @Override void shelf(LinearLayout target,JSONArray items,String type,boolean recent){
  HorizontalScrollView scroller=new HorizontalScrollView(this);scroller.setHorizontalScrollBarEnabled(false);scroller.setClipToPadding(false);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.TOP);
  int available=getResources().getDisplayMetrics().widthPixels-dp(32),width=recent?(available-dp(10))/2:(available-dp(20))/3;width=Math.min(width,dp(recent?220:150));
  for(int i=0;i<Math.min(items.length(),20);i++){JSONObject m=items.optJSONObject(i);if(m==null)continue;LinearLayout card=poster(m,type,width,recent);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(width,-2);lp.setMargins(0,0,dp(10),0);row.addView(card,lp);}scroller.addView(row);target.addView(scroller);

 }
 @Override LinearLayout poster(JSONObject metadata,String type,int width,boolean recent){
  if(metadata.has("fusion.site"))try{FusionArtwork.fill(metadata,FusionArtwork.cached(this,metadata));}catch(Exception ignored){}JSONObject item=metadata;if(recent)try{item=new JSONObject(metadata.toString());item.put("poster",metadata.optString("background",metadata.optString("poster")));}catch(Exception ignored){}
  try{item=new JSONObject(item.toString());item.put("poster","");}catch(Exception ignored){}
  LinearLayout c=super.poster(item,type,width,recent);c.setPadding(0,0,0,dp(6));
  if(c.getChildAt(0) instanceof FrameLayout){FrameLayout frame=(FrameLayout)c.getChildAt(0);frame.setBackground(rounded(card(),10));frame.setClipToOutline(true);frame.setLayoutParams(new LinearLayout.LayoutParams(width,recent?(int)(width/1.72):(int)(width*1.50)));
   if(homeChrome==null)homeChrome=new HomeChrome(this);homeChrome.decorateBadge(frame,metadata);
  }
  if(c.getChildCount()>1&&c.getChildAt(1) instanceof TextView){TextView title=(TextView)c.getChildAt(1);title.setTextSize(recent?12:11);title.setLines(2);title.setGravity(Gravity.CENTER);title.setPadding(dp(1),dp(6),dp(1),0);title.setTextColor(ink());}
  if(!recent){String release=metadata.optString("releaseInfo");if(!release.isEmpty()){TextView year=text(release,9,muted());year.setSingleLine();year.setEllipsize(TextUtils.TruncateAt.END);year.setGravity(Gravity.CENTER);year.setPadding(0,dp(3),0,0);c.addView(year);}}
  else if(c.getChildCount()>2&&c.getChildAt(2) instanceof TextView){TextView info=(TextView)c.getChildAt(2);info.setTextSize(10);info.setPadding(0,dp(3),0,0);info.setGravity(Gravity.CENTER);info.setTextColor(accent());}
  if(metadata.has("fusion.site")){c.setOnClickListener(v->openItem(metadata));TextView source=text("影视仓",9,accent());source.setGravity(Gravity.CENTER);source.setPadding(0,dp(3),0,0);c.addView(source);}
  if(c.getChildAt(0) instanceof FrameLayout){FrameLayout frame=(FrameLayout)c.getChildAt(0);for(int j=0;j<frame.getChildCount();j++)if(frame.getChildAt(j) instanceof ImageView){TvPosterImages.load(this,(ImageView)frame.getChildAt(j),recent?metadata.optString("background",metadata.optString("poster")):metadata.optString("poster"),width);break;}}
  if(metadata.has("fusion.site")&&metadata.optString("poster").isEmpty()){final int token=epoch;FusionArtwork.resolve(this,metadata,match->runOnUiThread(()->{if(token!=epoch||isFinishing())return;try{FusionArtwork.fill(metadata,match);FrameLayout frame=(FrameLayout)c.getChildAt(0);for(int j=0;j<frame.getChildCount();j++)if(frame.getChildAt(j) instanceof ImageView){TvPosterImages.load(this,(ImageView)frame.getChildAt(j),metadata.optString("poster"),width);break;}}catch(Exception ignored){}}));}
  return c;
 }
