 void chooseHero(JSONArray items,String type,String genre){int priority=genre.isEmpty()?(type.equals("series")?2:1):0;if(homeCanvas&&priority>heroPriority){heroPriority=priority;setHeroes(items,type);}}
 void setHeroes(JSONArray items,String type){if(heroSwipe!=null)heroSwipe.cancel();try{prefs.edit().putString(heroCacheKey(),new JSONObject().put("items",items).put("type",type).toString()).apply();}catch(Exception ignored){}heroes=new JSONArray();heroType=type;for(int i=0;i<Math.min(5,items.length());i++){JSONObject m=items.optJSONObject(i);if(m!=null)heroes.put(m);}heroIndex=0;showHero();carousel.removeCallbacks(tick);if(resumed&&heroes.length()>1)carousel.postDelayed(tick,7000);}
 void moveHero(int step){if(heroSwipe!=null&&heroes.length()>1){heroSwipe.advance(step);return;}commitHero(step);}
 void commitHero(int step){if(heroes.length()==0)return;heroIndex=CarouselRules.index(heroIndex,step,heroes.length());showHero();carousel.removeCallbacks(tick);if(resumed&&heroes.length()>1)carousel.postDelayed(tick,7000);}
 final Runnable tick=()->{if(homeCanvas&&resumed){moveHero(1);}};
 void showHero(){JSONObject m=heroes.optJSONObject(heroIndex);if(m==null||hero==null)return;bindHero(m);dots.removeAllViews();for(int i=0;i<heroes.length();i++){final int index=i;View dot=new View(this);dot.setBackground(rounded(i==heroIndex?0xffc0e1f5:0x7099b4be,4));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(i==heroIndex?17:5),dp(5));p.setMargins(dp(3),0,dp(3),0);dots.addView(dot,p);dot.setOnClickListener(v->moveHero(index-heroIndex));}
  if(heroSwipe!=null)heroSwipe.refresh();
  if(m.has("fusion.site"))return;
  String id=m.optString("id"),type=m.optString("type",heroType),key="cinema.meta."+type+"."+id;try{JSONObject cached=new JSONObject(prefs.getString(key,""));bindHero(cached);return;}catch(Exception ignored){}
  final int ticket=epoch;job(()->{try{JSONObject meta=CinemaCatalogClient.json("https://v3-cinemeta.strem.io/meta/"+type+"/"+Net.esc(id)+".json").getJSONObject("meta");prefs.edit().putString(key,meta.toString()).apply();runOnUiThread(()->{JSONObject active=heroes.optJSONObject(heroIndex);if(ticket==epoch&&homeCanvas&&active!=null&&id.equals(active.optString("id")))bindHero(meta);});}catch(Exception ignored){}});
 }
 void bindHero(JSONObject m){if(heroSwipe!=null&&heroSwipe.busy()){final int token=epoch;final String id=m.optString("id");carousel.postDelayed(()->{JSONObject current=heroes.optJSONObject(heroIndex);if(token==epoch&&homeCanvas&&current!=null&&id.equals(current.optString("id")))bindHero(m);},360);return;}boolean artwork=!m.optString("background",m.optString("poster")).isEmpty();hero.getLayoutParams().height=artwork?Math.min(dp(480),(int)(getResources().getDisplayMetrics().widthPixels*1.12)):dp(220);hero.requestLayout();heroImage.setImageDrawable(null);TvPosterImages.load(this,heroImage,m.optString("background",m.optString("poster")),getResources().getDisplayMetrics().widthPixels);String logo=m.optString("logo");heroLogo.setImageDrawable(null);heroLogo.setVisibility(logo.isEmpty()?View.GONE:View.VISIBLE);heroTitle.setVisibility(View.VISIBLE);if(!logo.isEmpty())TvPosterImages.load(this,heroLogo,logo,dp(320));if(homeChrome==null)homeChrome=new HomeChrome(this);homeChrome.bindHeroText(m);}
