 void fusionHome(){final int ticket=epoch;final String sourceId=prefs.getString("home.source.v1","fty");LinearLayout target=new LinearLayout(this);target.setOrientation(1);body.addView(target);target.addView(heading("影视仓片库"));target.addView(text("正在读取影片…",12,muted()));
  FusionCatalog.IO.execute(()->{if(ticket!=epoch)return;try{FusionCatalog.Session session=HomeSources.session(this,sourceId);runOnUiThread(()->{if(ticket==epoch&&!isFinishing())fusionSession=session;});String homeKey="fusion.home:"+session.url+"|"+session.site.optString("key");JSONObject response;String saved=prefs.getString(homeKey,"");response=saved.isEmpty()?null:new JSONObject(saved);if(response==null||response.optJSONArray("class")==null||response.optJSONArray("class").length()==0){prefs.edit().remove(homeKey).apply();response=FusionCatalog.request(this,session,"home","","",1);}JSONArray categories=response.optJSONArray("class");if(categories==null||categories.length()==0){prefs.edit().remove(homeKey).apply();throw new Exception(session.site.optString("name")+"：站点没有返回分类，请切换站点");}prefs.edit().putString(homeKey,response.toString()).apply();runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;fusionSession=session;target.removeAllViews();target.addView(heading("影视仓 · "+session.site.optString("name")));LinearLayout actions=new LinearLayout(this);actions.addView(button("完整片库",()->openFusion("")),new LinearLayout.LayoutParams(0,dp(44),1));if(!CmsApi.MARKER.equals(session.site.optString("api")))actions.addView(button("切换站点",()->chooseFusionSite()),new LinearLayout.LayoutParams(0,dp(44),1));actions.addView(button("刷新",()->refreshFusion()),new LinearLayout.LayoutParams(0,dp(44),1));target.addView(actions);String checked="自定义接口 · 按实际播放结果为准";TextView note=text(checked,10,muted());target.addView(note);
   JSONArray selected=new JSONArray();for(String wanted:new String[]{"每日更新","电影","电视剧"})for(int i=0;i<categories.length();i++){JSONObject c=categories.optJSONObject(i);if(c!=null&&wanted.equals(c.optString("type_name")))selected.put(c);}if(selected.length()==0)for(int i=0;i<Math.min(3,categories.length());i++)selected.put(categories.optJSONObject(i));
   for(int i=0;i<selected.length();i++){JSONObject c=selected.optJSONObject(i);if(c==null)continue;TextView heading=heading("影视仓 · "+c.optString("type_name")+" ›");heading.setOnClickListener(v->openFusion(c.optString("type_id")));target.addView(heading);LinearLayout shelf=new LinearLayout(this);shelf.setOrientation(1);target.addView(shelf);fusionShelf(shelf,session,c,ticket,i==0);}
  });}catch(Exception e){runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();target.addView(heading("影视仓片库"));target.addView(text("读取失败："+(e.getMessage()==null?"站点暂未响应":e.getMessage()),12,muted()));if(fusionSession!=null){target.addView(text("当前站点："+fusionSession.site.optString("name"),12,muted()));target.addView(button("切换站点",()->chooseFusionSite()));}target.addView(button("重新读取目录",()->refreshFusion()));target.addView(button("管理接口",()->startActivity(new Intent(this,TvBoxActivity.class))));});}});
 }
 void fusionShelf(LinearLayout target,FusionCatalog.Session s,JSONObject c,int ticket,boolean lead){String category=c.optString("type_id"),key=FusionCatalog.cacheKey(s,category);boolean cached=false;try{JSONArray items=new JSONArray(prefs.getString(key,""));if(items.length()>0){if(lead){heroPriority=3;setHeroes(items,"movie");}shelf(target,items,"movie",false);cached=true;}}catch(Exception ignored){}
  if(cached&&System.currentTimeMillis()-prefs.getLong(key+".time",0)<6*60*60*1000L)return;if(!cached)target.addView(text("正在读取真实条目…",12,muted()));FusionCatalog.IO.execute(()->{if(ticket!=epoch)return;try{JSONObject r=FusionCatalog.request(this,s,"category",category,"",1);JSONArray items=FusionCatalog.normalize(s,r.optJSONArray("list"),category);if(items.length()==0)throw new Exception("此分类暂无条目");prefs.edit().putString(key,items.toString()).putLong(key+".time",System.currentTimeMillis()).apply();runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();if(lead){heroPriority=3;setHeroes(items,"movie");}shelf(target,items,"movie",false);});}catch(Exception e){runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;if(target.getChildCount()==1&&target.getChildAt(0) instanceof TextView){TextView note=(TextView)target.getChildAt(0);note.setText("目录暂未返回 · 点此重试");note.setOnClickListener(v->fusionShelf(target,s,c,ticket,lead));}});}});
 }
 void chooseFusionSite(){if(fusionSession==null)return;JSONArray sites=fusionSession.config.optJSONArray("sites");java.util.ArrayList<JSONObject> candidates=new java.util.ArrayList<>();java.util.ArrayList<String> names=new java.util.ArrayList<>();for(int i=0;sites!=null&&i<sites.length();i++){JSONObject s=sites.optJSONObject(i);if(s==null||s.optInt("type",3)!=3)continue;candidates.add(s);names.add(s.optString("name")+(s.optString("api").equals("csp_AListSh")?" · 小雅样本已验证":" · 待实播验证"));}new AlertDialog.Builder(this).setTitle("影视仓首页来源").setItems(names.toArray(new String[0]),(d,n)->{prefs.edit().putString("fusion.site:"+fusionSession.url,candidates.get(n).optString("key")).apply();home();}).show();}
 void refreshFusion(){if(fusionSession==null){home();return;}String prefix="fusion.catalog.v3:"+fusionSession.url+"|"+fusionSession.site.optString("key")+"|";android.content.SharedPreferences.Editor editor=prefs.edit();for(String key:prefs.getAll().keySet())if(key.startsWith(prefix))editor.remove(key);editor.remove("fusion.home:"+fusionSession.url+"|"+fusionSession.site.optString("key")).apply();home();}


 void recolor(View view){if(view instanceof TextView){TextView t=(TextView)view;int c=t.getCurrentTextColor();if(map(c)!=c)t.setTextColor(map(c));}Drawable d=view.getBackground();if(d instanceof ColorDrawable){int c=((ColorDrawable)d).getColor();if(map(c)!=c)((ColorDrawable)d).setColor(map(c));}else if(d instanceof GradientDrawable){ColorStateList c=((GradientDrawable)d).getColor();if(c!=null&&map(c.getDefaultColor())!=c.getDefaultColor())((GradientDrawable)d).setColor(map(c.getDefaultColor()));}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)recolor(((ViewGroup)view).getChildAt(i));}
